edits.old:
const saved = localStorage.getItem('theme');
if (saved === 'light') {
  root.classList.add('light');
  btn.textContent = '☀️ 라이트';
}

edits.new:
const saved = localStorage.getItem('theme');
if (saved === 'dark') {
  root.classList.remove('light');
  btn.textContent = '🌙 다크';
} else {
  root.classList.add('light');
  btn.textContent = '☀️ 라이트';
}
